insert into public.settings (key, value, updated_by) values
  ('admin', '{"admin_email": "swallehmtawazo@gmail.com"}'::jsonb, 'seed')
insert into public.settings (key, value, updated_by) values
  ('calendar', '{"timezone": "Africa/Nairobi", "send_days": ["mon", "tue", "wed", "thu", "fri"], "holidays": [{"date": "2026-10-10", "name": "Utamaduni / Moi Day"}, {"date": "2026-10-20", "name": "Mashujaa Day"}, {"date": "2026-12-12", "name": "Jamhuri Day"}, {"date": "2026-12-25", "name": "Christmas Day"}, {"date": "2026-12-26", "name": "Boxing Day"}, {"date": "2027-01-01", "name": "New Year''s Day"}, {"date": "2027-03-26", "name": "Good Friday"}, {"date": "2027-03-29", "name": "Easter Monday"}, {"date": "2027-05-01", "name": "Labour Day"}, {"date": "2027-06-01", "name": "Madaraka Day"}, {"date": "2027-10-11", "name": "Utamaduni / Moi Day (observed)"}, {"date": "2027-10-20", "name": "Mashujaa Day"}, {"date": "2027-12-13", "name": "Jamhuri Day (observed)"}, {"date": "2027-12-27", "name": "Christmas Day (observed)"}], "pauses": [{"start": "2026-12-21", "end": "2027-01-01", "name": "December break"}], "pauses_block_followups": true, "followups": {"fu1_working_days": 3, "fu2_working_days": 8, "demo_fu_working_days": [1, 4]}, "pacing": {"max_per_hour": 15, "batch_windows": [{"start": "09:30", "end": "11:00"}, {"start": "14:00", "end": "15:30"}]}, "same_day_demo_cutoff": "17:00"}'::jsonb, 'seed'),
  ('subcategories', '{"property_agency": {"label": "Property agencies", "list_day": "mon", "template": "property_agency"}, "land_developers": {"label": "Land & developers", "list_day": "tue", "template": "land_developers"}, "construction": {"label": "Construction", "list_day": "wed", "template": "construction"}, "hardware_supplies": {"label": "Hardware & supplies", "list_day": "thu", "template": "hardware_supplies"}, "roofing_steel": {"label": "Roofing & steel", "list_day": "fri", "template": "roofing_steel"}}'::jsonb, 'seed'),
  ('scoring', '{"web_min_score": 65.0, "content_min_score": 62.0, "social_state_bonus": {"none": 5.0, "stale": 5.0, "active": 0.0}, "social_state_skip": ["polished"]}'::jsonb, 'seed'),
  ('messaging', '{"signoff": "— Swalleh, Raswal Tech Solutions", "length": {"min": 280, "max": 480}}'::jsonb, 'seed'),
  ('budget', '{"places_calls_per_month": 900, "places_calls_per_night": 40, "psi_calls_per_night": 150, "gemini_calls_per_night": 60, "db_cap_mb": 400, "storage_cap_mb": 800}'::jsonb, 'seed'),
  ('quick_replies', '[{"key": "price_web", "label": "How much? (website)", "text": "Websites like the preview start from KES 30,000 depending on pages and features. Should I send the live preview first so you can see exactly what you''d get?", "action": null}, {"key": "price_content", "label": "How much? (content)", "text": "Content packages start from KES 6,000 a month, or per piece. Want to see the full sample set first?", "action": null}, {"key": "who", "label": "Who is this?", "text": "I''m Swalleh from Raswal Tech Solutions, a web and content studio in Nairobi. I found {business} on Google Maps; your number is on the listing. If you''d prefer I don''t message again, just say so.", "action": null}, {"key": "has_provider", "label": "We already have someone", "text": "Great, glad you''re covered. Keep the preview, and all the best!", "action": "lost_has_provider"}, {"key": "not_now", "label": "Not now", "text": "No problem at all. Should I check back in January?", "action": "snooze"}, {"key": "stop", "label": "Stop / not interested", "text": "Sorry for the bother, I won''t message again.", "action": "opt_out"}, {"key": "holding", "label": "Demo tomorrow (over cap)", "text": "Thanks! I''ll have it ready for you tomorrow morning.", "action": null}]'::jsonb, 'seed'),
  ('followup_templates', '{"fu1": "Hi {business} team, just checking you saw the preview I sent on {weekday}? Happy to share the live link; it takes a minute to look through. — Swalleh", "fu2_web": "Hi {business} team, one last note from me. If a website isn''t a priority right now, the preview is yours to keep. If you''d like, I can send the live version so you can click through it on your phone. If now isn''t the right time, no problem at all, I won''t keep messaging. — Swalleh", "fu2_content": "Hi {business} team, one last note from me. I can send the full sample set (posters and a short video idea) so you can see how it would look on your pages week to week. If now isn''t the right time, no problem at all, I won''t keep messaging. — Swalleh", "demo_fu1": "Hi {business} team, did you get a chance to open the preview link? Happy to change anything you''d like to see. — Swalleh", "demo_fu2": "Hi {business} team, just following up on the preview. Shall we go ahead, or is there anything you''d like adjusted first? — Swalleh"}'::jsonb, 'seed'),
  ('demo_cap', '{"web": 3, "content": 3}'::jsonb, 'seed'),
  ('daily_targets', '{"web": 20, "content": 10}'::jsonb, 'seed'),
  ('pause_list', '[]'::jsonb, 'seed')
